use std::{env,fs,path::Path};
use wasmc::lib_tool_rust_consumer_sdk::native_build::NativePinnedFile;
use wasmc::lib_tool_rust_consumer_sdk::native_build::host::{compile_host_canonical_source,HostContract,HostContractPair};
use wasmc::canonical_host_assets::{compile_canonical_host_assets,CanonicalAssetBuffers};
fn sha(b:&[u8])->String{wasmc::self_bundle::hex(&wasmc::self_bundle::sha256(b))}
fn contract(dir:&Path,selection:&[&str])->HostContract{let f=|n|fs::read(dir.join(n)).unwrap();let (wit,execution_abi,provider_contract,binding)=(f("lib.wit"),f("execution-abi.json"),f("provider-contract.json"),f("binding.json"));HostContract{schema:"wasmc.canonical-host-contract/v1".into(),wit_sha256:sha(&wit),execution_abi_sha256:sha(&execution_abi),provider_contract_sha256:sha(&provider_contract),binding_sha256:sha(&binding),wit,execution_abi,provider_contract,binding,selected_operations:vec![],operation_selection:Some(selection.iter().map(|x|x.to_string()).collect())}}
fn pins(h:&HostContract)->Vec<u8>{[&h.wit_sha256,&h.execution_abi_sha256,&h.provider_contract_sha256,&h.binding_sha256].iter().flat_map(|s|(0..64).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap())).collect()}
fn main(){let a:Vec<String>=env::args().collect();let root=Path::new(&a[1]);let hostroot=Path::new(&a[2]);let out=Path::new(&a[3]);let source=fs::read_to_string(&a[4]).unwrap();let activation=fs::read(&a[5]).unwrap();let template=fs::read(&a[6]).unwrap();let host=HostContractPair{entry:contract(&hostroot.join("entry"),&[]),operations:contract(&hostroot.join("operations"),&["table.transact"])};let pin=sha(&fs::read(root.join("lib.json")).unwrap());let app=compile_host_canonical_source(&source,root,&pin,&host,17).unwrap();let ep=pins(&host.entry);let op=pins(&host.operations);let frame=compile_canonical_host_assets(&source,CanonicalAssetBuffers{entry:[&host.entry.wit,&host.entry.execution_abi,&host.entry.provider_contract,&host.entry.binding,&ep],extension:[&activation,&app.lib_artifact,&app.lib_wit,&template,&host.operations.wit,&host.operations.execution_abi,&host.operations.provider_contract,&host.operations.binding,&op]}).unwrap();fs::write(out.join("native.frame"),&frame).unwrap();let pinned=|p:&str|NativePinnedFile{path:Path::new(p).into(),sha256:sha(&fs::read(p).unwrap())};let sealed=out.join("native-sealed");app.seal(&host,&pinned(&a[7]),&pinned(&a[8]),&pinned(&a[9]),&sealed).unwrap();for (name,index) in [("caller.wasm",1),("lib-projection.wasm",3),("lib-calls.wasm",4),("canonical-entry.wasm",5),("app-projection.wasm",6),("host-entry.wasm",7),("host-projection.wasm",8),("host-calls.wasm",9)] {assert!(fs::read(sealed.join(format!("input-{index}.wasm"))).unwrap()==fs::read(out.join(name)).unwrap(),"sealed module mismatch {name}");} /* raw module comparisons removed: sealed outputs are authoritative */ /* [("caller.wasm",app.caller),("lib-projection.wasm",app.projection),("lib-calls.wasm",app.calls),("canonical-entry.wasm",app.entry),("app-projection.wasm",app.app_projection),("host-entry.wasm",app.host_entry),("host-projection.wasm",app.host_projection),("host-calls.wasm",app.host_calls)] {let actual=fs::read(out.join(name)).unwrap();println!("raw_native {name} equal={} native={} portable={}",b==actual,sha(&b),sha(&actual));}*/ assert!(frame==fs::read(out.join("frame.bin")).unwrap(),"native frontend frame mismatch {}",sha(&frame));println!("native frame {} and eight sealed modules match",sha(&frame));}
